/**
 * Install-as-an-app (PWA) pieces for the admin dashboard: web manifest, service
 * worker and icons. Served by routes/admin.ts under /admin/.
 *
 * The service worker only keeps the page shell (which holds no data) so the
 * app opens instantly and shows a friendly offline note. It never touches
 * /admin/api/*: every number and every sign-in always comes from the server.
 */

export const ICON_192 = "";
export const ICON_512 = "";

export const ADMIN_MANIFEST = JSON.stringify({
  name: "Gracerandly admin",
  short_name: "GR Admin",
  description: "Staff dashboard for Gracerandly",
  id: "/admin/",
  start_url: "/admin/",
  scope: "/admin/",
  display: "standalone",
  orientation: "any",
  background_color: "#F9F4E8",
  theme_color: "#502D55",
  icons: [
    { src: "/admin/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
    { src: "/admin/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
    { src: "/admin/icon-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
  ],
});

/** Bump CACHE when the page shell changes shape so old copies are dropped. */
export const ADMIN_SW = String.raw`
const CACHE = "gr-admin-shell-v1";
const SHELL = "/admin/";
self.addEventListener("install", (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.add(SHELL)).then(() => self.skipWaiting()));
});
self.addEventListener("activate", (e) => {
  e.waitUntil(
    caches.keys().then((ks) => Promise.all(ks.filter((k) => k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim())
  );
});
self.addEventListener("fetch", (e) => {
  const req = e.request;
  const url = new URL(req.url);
  if (req.method !== "GET" || url.origin !== location.origin) return;
  if (url.pathname.startsWith("/admin/api/")) return; // live data is never cached
  if (req.mode === "navigate" && (url.pathname === "/admin/" || url.pathname === "/admin")) {
    e.respondWith(
      fetch(req)
        .then((r) => {
          if (r.ok) { const copy = r.clone(); caches.open(CACHE).then((c) => c.put(SHELL, copy)); }
          return r;
        })
        .catch(() => caches.match(SHELL).then((r) => r || new Response("You are offline. Reconnect and reopen the app.", { status: 503, headers: { "content-type": "text/plain" } })))
    );
  }
});
`;
